const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

// Read the controller actually connected to the page, not a test-only copy.
// Existing tests inspect both static HTML and markup generated by this script.
module.exports = function readTaskPageSource() {
  const root = path.resolve(__dirname, '../../sorter 2025');
  const html = fs.readFileSync(path.join(root, 'tasks.html'), 'utf8');
  assert.match(html, /<script src="tasks-page\.js(?:\?[^"<>]*)?"><\/script>/);
  return html + '\n' + fs.readFileSync(path.join(root, 'tasks-page.js'), 'utf8');
};
